import{_ as t,o as i,c as n,a2 as r}from"./chunks/framework.vLhlLNVn.js";const m=JSON.parse('{"title":"Installation und Voraussetzungen","description":"","frontmatter":{"order":1,"adapter":"wled","editLink":"https://github.com/DrozmotiX/ioBroker.wled/edit/main/docs/de/01.erste-schritte/01.installation.md"},"headers":[],"relativePath":"de/adapter/wled/erste-schritte/installation.md","filePath":"de/adapter/wled/erste-schritte/installation.md","lastUpdated":null}'),a={name:"de/adapter/wled/erste-schritte/installation.md"};function d(s,e,o,l,u,h){return i(),n("div",null,[...e[0]||(e[0]=[r(`<h1 id="installation-und-voraussetzungen" tabindex="-1">Installation und Voraussetzungen <a class="header-anchor" href="#installation-und-voraussetzungen" aria-label="Permalink to &quot;Installation und Voraussetzungen&quot;">​</a></h1><p><a id="wled-firmware-requirements-adapter-need"></a></p><h2 id="welche-wled-firmware-und-welche-voraussetzungen-braucht-der-adapter" tabindex="-1">Welche WLED-Firmware und welche Voraussetzungen braucht der Adapter? <a class="header-anchor" href="#welche-wled-firmware-und-welche-voraussetzungen-braucht-der-adapter" aria-label="Permalink to &quot;Welche WLED-Firmware und welche Voraussetzungen braucht der Adapter?&quot;">​</a></h2><p><strong>Kurz:</strong> Der Adapter ist mit WLED 0.14 und 0.15 getestet. In v0.9.2 braucht er Node.js 20 oder neuer, js-controller 6.0.11 oder neuer und Admin 7.6.17 oder neuer. Das WLED-Gerät muss vom ioBroker-Host aus per HTTP erreichbar sein, unverschlüsselt und ohne Anmeldung.</p><h3 id="wled-firmware" tabindex="-1">WLED-Firmware <a class="header-anchor" href="#wled-firmware" aria-label="Permalink to &quot;WLED-Firmware&quot;">​</a></h3><ul><li>Getestet ist der Adapter mit WLED 0.14 und 0.15. Eine Mindestversion prüft er nicht. Du kannst Geräte mit unterschiedlicher Firmware an derselben Instanz betreiben.</li><li>Ab WLED 0.12 verbindet sich der Adapter zusätzlich per WebSocket. Änderungen am Gerät kommen dann sofort in ioBroker an.</li><li>Firmware ohne WebSocket (älter als 0.12) fragt der Adapter nur per HTTP ab, im Takt des Polling-Intervalls. Im Log steht dann die Warnung <code>Client 192.168.x.y does not support websocket, please consider upgrading your WLED firmware to &gt;= 0.12. Switching to http-APi !</code>. Aktualisiere in diesem Fall die Firmware.</li></ul><h3 id="iobroker" tabindex="-1">ioBroker <a class="header-anchor" href="#iobroker" aria-label="Permalink to &quot;ioBroker&quot;">​</a></h3><ul><li>Node.js 20 oder neuer</li><li>js-controller 6.0.11 oder neuer</li><li>Admin 7.6.17 oder neuer</li></ul><p><strong>Ab v0.9.3:</strong> Der Adapter braucht Node.js 22 oder neuer und Admin 7.6.20 oder neuer. js-controller 6.0.11 reicht weiterhin. Prüfe das vor dem Update.</p><h3 id="netzwerk" tabindex="-1">Netzwerk <a class="header-anchor" href="#netzwerk" aria-label="Permalink to &quot;Netzwerk&quot;">​</a></h3><ul><li>Der Adapter spricht jedes Gerät direkt über seine IP-Adresse an: per HTTP unter <code>http://192.168.x.y/json</code> und per WebSocket unter <code>ws://192.168.x.y/ws</code>. Beides muss vom ioBroker-Host aus erreichbar sein.</li><li>Die Verbindung ist unverschlüsselt und ohne Anmeldung. HTTPS oder einen Zugang mit Benutzername und Passwort kennt der Adapter nicht. Liegt das Gerät hinter einem Proxy, der so etwas verlangt, erreicht der Adapter es nicht.</li><li>Gib dem Gerät im Router eine feste IP-Adresse. Beim Start verbindet sich der Adapter mit allen bekannten Geräten über die IP-Adresse, die er gespeichert hat.</li><li>Für die automatische Suche per Bonjour (mDNS) müssen ioBroker und WLED im selben Netz liegen, und Multicast muss zwischen beiden durchkommen. In Netzen mit VLAN-Trennung klappt die Suche meist nicht. Dann fügst du das Gerät per IP-Adresse hinzu.</li></ul><p><strong>Siehe auch:</strong> <a href="./erstes-geraet#adapter-wled-devices-automatically">Wie und wann findet der Adapter meine WLED-Geräte automatisch?</a> · <a href="./erstes-geraet#add-device-manually-ip-if">Wie füge ich ein Gerät manuell per IP hinzu?</a> · <a href="./../hintergrund/verbindung-und-aktualisierung#states-only-updated-after-30">Warum werden Zustände erst nach 30 Sekunden aktualisiert?</a> · <a href="./../fehlerbehebung/verbindung-und-start#adapter-not-start-stop-responding">Warum startet der Adapter nach einem Update nicht?</a></p><p><a id="magic-home-ready-made-wled"></a></p><h2 id="funktionieren-magic-home-und-fertige-wled-controller-mit-dem-adapter" tabindex="-1">Funktionieren Magic Home und fertige WLED-Controller mit dem Adapter? <a class="header-anchor" href="#funktionieren-magic-home-und-fertige-wled-controller-mit-dem-adapter" aria-label="Permalink to &quot;Funktionieren Magic Home und fertige WLED-Controller mit dem Adapter?&quot;">​</a></h2><p><strong>Kurz:</strong> Der Adapter funktioniert mit jedem Controller, auf dem die WLED-Firmware läuft, auch mit fertig gekauften Controllern, die WLED schon mitbringen. Magic-Home-Controller laufen mit ihrer eigenen Firmware und funktionieren mit diesem Adapter nicht, außer du hast sie mit WLED neu bespielt.</p><p>Der Adapter spricht nur die Schnittstellen der WLED-Firmware an: die JSON-API unter <code>http://192.168.x.y/json</code> und den WebSocket unter <code>ws://192.168.x.y/ws</code>. Die automatische Suche fragt nach dem Bonjour-Dienst <code>wled</code>, den nur WLED im Netz anbietet. Ein Controller mit anderer Firmware antwortet darauf nicht und taucht deshalb weder in der Suche noch nach „Gerät hinzufügen“ auf.</p><h3 id="so-prufst-du-ob-dein-controller-wled-nutzt" tabindex="-1">So prüfst du, ob dein Controller WLED nutzt <a class="header-anchor" href="#so-prufst-du-ob-dein-controller-wled-nutzt" aria-label="Permalink to &quot;So prüfst du, ob dein Controller WLED nutzt&quot;">​</a></h3><ol><li>Öffne im Browser <code>http://192.168.x.y</code> mit der IP-Adresse des Controllers. Bei WLED erscheint die WLED-Oberfläche mit Farbrad, Effekten und Presets.</li><li>Öffne <code>http://192.168.x.y/json/info</code>. Bei WLED kommt ein JSON-Text zurück, darin unter anderem <code>&quot;ver&quot;</code> mit der WLED-Version und <code>&quot;brand&quot;:&quot;WLED&quot;</code>.</li><li>Kommt eine andere Oberfläche, eine Fehlerseite oder gar keine Antwort, läuft auf dem Controller keine WLED-Firmware. Dann brauchst du einen anderen Adapter oder musst den Controller mit WLED neu bespielen.</li></ol><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Wie du einen Controller mit WLED bespielst, steht in der Anleitung des WLED-Projekts. Das hat mit dem Adapter nichts zu tun und wird hier nicht beschrieben.</p></div><p><strong>Siehe auch:</strong> <a href="#wled-firmware-requirements-adapter-need">Welche WLED-Firmware und welche Voraussetzungen braucht der Adapter?</a> · <a href="./erstes-geraet#add-device-manually-ip-if">Wie füge ich ein Gerät manuell per IP hinzu?</a></p><p><a id="install-adapter-github-initialise-not"></a></p><h2 id="wie-installiere-ich-den-adapter-von-github-und-was-bedeutet-initialise-is-not-defined" tabindex="-1">Wie installiere ich den Adapter von GitHub, und was bedeutet &quot;initialise is not defined&quot;? <a class="header-anchor" href="#wie-installiere-ich-den-adapter-von-github-und-was-bedeutet-initialise-is-not-defined" aria-label="Permalink to &quot;Wie installiere ich den Adapter von GitHub, und was bedeutet &quot;initialise is not defined&quot;?&quot;">​</a></h2><p><strong>Kurz:</strong> Installiere den Adapter normalerweise nicht von GitHub, sondern im Admin im Reiter „Adapter“ aus dem Repository. Der Stand auf GitHub ist ein Entwicklungsstand und kann Fehler enthalten, die es in keiner veröffentlichten Version gibt. Die Meldung <code>initialise is not defined</code> stammt aus Adapterversionen von Anfang 2021. Installierst du die aktuelle Version aus dem Repository, ist sie weg.</p><h3 id="so-installierst-du-den-adapter" tabindex="-1">So installierst du den Adapter <a class="header-anchor" href="#so-installierst-du-den-adapter" aria-label="Permalink to &quot;So installierst du den Adapter&quot;">​</a></h3><ol><li>Öffne im Admin den Reiter „Adapter“.</li><li>Suche nach „WLED“.</li><li>Dreh die Kachel über die drei Punkte um und klicke auf „Instanz hinzufügen“. Der Admin installiert dabei den Adapter und legt die Instanz <code>wled.0</code> an.</li><li>Öffne die Instanz und prüfe, ob sie startet. Die ersten Geräte sucht der Adapter beim Start von selbst.</li></ol><p>Welche Version du bekommst, hängt vom Repository ab, das in den Systemeinstellungen aktiv ist: „stable“ enthält geprüfte Versionen, „beta“ (früher „latest“) die Versionen in der Testphase. Wie du das Repository wechselst oder einen einzelnen Adapter in der Beta-Version installierst, steht in der ioBroker-Doku unter <a href="https://www.iobroker.net/#de/documentation/basics/repositories.md" target="_blank" rel="noreferrer">Was ist ein Repository?</a>.</p><h3 id="installation-von-github" tabindex="-1">Installation von GitHub <a class="header-anchor" href="#installation-von-github" aria-label="Permalink to &quot;Installation von GitHub&quot;">​</a></h3><p>Von GitHub installierst du nur, wenn der Entwickler dich in einem Issue ausdrücklich darum bittet, zum Beispiel um eine Fehlerbehebung vor dem Release zu testen. Der Weg führt im Reiter „Adapter“ über den Knopf mit der Octocat (Expertenmodus) und den Reiter „Von GitHub“ oder „Benutzerdefiniert“ mit der Adresse <code>https://github.com/DrozmotiX/ioBroker.wled</code>. Abhängigkeiten prüft ioBroker auf diesem Weg nicht. Kehre nach dem Test zur Version aus dem Repository zurück.</p><h3 id="was-„initialise-is-not-defined-bedeutet" tabindex="-1">Was „initialise is not defined“ bedeutet <a class="header-anchor" href="#was-„initialise-is-not-defined-bedeutet" aria-label="Permalink to &quot;Was „initialise is not defined“ bedeutet&quot;">​</a></h3><p>So sah die Meldung aus, sie wiederholte sich nach dem Hinzufügen eines Geräts immer wieder:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Create state error = ReferenceError: initialise is not defined</span></span></code></pre></div><p>Der Adapter rief damals beim Anlegen der Datenpunkte eine Funktion auf, die es im Code nicht gab. Im heutigen Code kommt sie nicht mehr vor. Siehst du die Meldung, läuft bei dir eine alte Version oder ein alter Stand von GitHub.</p><ol><li>Installiere über die vorhandene Version die aktuelle Version aus dem Repository: im Reiter „Adapter“ auf der Rückseite der WLED-Kachel über „Eine bestimmte Version installieren“. Lösche den Adapter dafür nicht, sonst gehen die Instanz und ihre Objekte verloren.</li><li>Starte die Instanz neu.</li><li>Prüfe im Log, ob die Meldung verschwunden ist.</li></ol><p><strong>Siehe auch:</strong> <a href="#install-update-fail-no-matching">Warum schlägt die Installation oder das Update mit &quot;no matching version found&quot; fehl?</a> · <a href="./../fehlerbehebung/verbindung-und-start#adapter-not-start-stop-responding">Warum startet der Adapter nach einem Update nicht?</a></p><p><a id="install-update-fail-no-matching"></a></p><h2 id="warum-schlagt-die-installation-oder-das-update-mit-no-matching-version-found-fehl" tabindex="-1">Warum schlägt die Installation oder das Update mit &quot;no matching version found&quot; fehl? <a class="header-anchor" href="#warum-schlagt-die-installation-oder-das-update-mit-no-matching-version-found-fehl" aria-label="Permalink to &quot;Warum schlägt die Installation oder das Update mit &quot;no matching version found&quot; fehl?&quot;">​</a></h2><p><strong>Kurz:</strong> Die Meldung kommt von npm: Die Version, die ioBroker installieren will, gibt es dort nicht. Meist ist die Adapterliste im Admin veraltet oder du hast eine Versionsnummer von Hand eingegeben, die nie veröffentlicht wurde. Lade die Adapterliste neu und installiere eine Version, die der Admin dir anbietet.</p><p>So sieht die Meldung aus:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>npm ERR! code ETARGET</span></span>
<span class="line"><span>npm ERR! notarget No matching version found for iobroker.wled@0.6.1.</span></span></code></pre></div><h3 id="so-liest-du-die-versionsnummern" tabindex="-1">So liest du die Versionsnummern <a class="header-anchor" href="#so-liest-du-die-versionsnummern" aria-label="Permalink to &quot;So liest du die Versionsnummern&quot;">​</a></h3><ul><li>Die Nummer hat drei Teile, zum Beispiel <code>0.9.2</code>. Der letzte Teil steigt bei Fehlerbehebungen, der mittlere bei neuen Funktionen.</li><li>Nicht jede Nummer wird veröffentlicht. So gab es 0.6.1 und 0.6.2 nie im Repository, auf 0.6.0 folgte dort 0.6.3.</li><li>Eine Nummer mit Zusatz ist eine Vorabversion, zum Beispiel <code>0.6.0-3</code> oder <code>0.9.3-beta.0</code>. Sie ist <strong>kleiner</strong> als die Version ohne Zusatz: <code>0.6.0-3</code> kommt vor <code>0.6.0</code>, nicht danach.</li></ul><h3 id="so-installierst-du-eine-passende-version" tabindex="-1">So installierst du eine passende Version <a class="header-anchor" href="#so-installierst-du-eine-passende-version" aria-label="Permalink to &quot;So installierst du eine passende Version&quot;">​</a></h3><ol><li>Öffne im Admin den Reiter „Adapter“ und klicke in der Werkzeugleiste auf „Adapter auf Updates überprüfen“. Der Admin lädt dann die Adapterliste neu.</li><li>Installiere die Version, die beim WLED-Adapter als verfügbar angezeigt wird.</li><li>Willst du eine andere Version, dreh die Kachel über die drei Punkte um und wähle „Eine bestimmte Version installieren“. Die Liste zeigt nur Versionen, die es wirklich gibt.</li><li>Die Versionen, die das aktive Repository anbietet, hängen von deiner Einstellung „stable“ oder „beta“ ab. Wie du das umstellst, steht in der ioBroker-Doku unter <a href="https://www.iobroker.net/#de/documentation/basics/repositories.md" target="_blank" rel="noreferrer">Was ist ein Repository?</a>.</li></ol><p>Alle veröffentlichten Versionen mit ihren Änderungen findest du auch auf GitHub unter <a href="https://github.com/DrozmotiX/ioBroker.wled/releases" target="_blank" rel="noreferrer">Releases</a> und im Changelog der <a href="https://github.com/DrozmotiX/ioBroker.wled#changelog" target="_blank" rel="noreferrer">README</a>.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Lehnt der Admin das Update ab, weil eine Voraussetzung fehlt, ist das ein anderer Fall. Dann zeigt der Update-Dialog die fehlende Voraussetzung in Rot, zum Beispiel eine zu alte Node.js- oder Admin-Version. Aktualisiere zuerst diese und danach den Adapter.</p></div><p><strong>Siehe auch:</strong> <a href="#wled-firmware-requirements-adapter-need">Welche WLED-Firmware und welche Voraussetzungen braucht der Adapter?</a> · <a href="#install-adapter-github-initialise-not">Wie installiere ich den Adapter von GitHub?</a></p>`,46)])])}const p=t(a,[["render",d]]);export{m as __pageData,p as default};
